import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { uv, vec3, mix, smoothstep, time, uniform, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, Vector3 } = ctx.THREE;

  const group = new Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Color palette from spec
  const colors = {
    background: 0x0b0b10,
    surface: 0x14141a,
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    gradTop: 0x101017,
    gradBottom: 0x1a1a22,
  };

  // Grid layout constants
  const dominantWidth = 3.25;
  const dominantHeight = 3.5;
  const secondaryWidth = 2.0;
  const secondaryHeight = 1.625;
  const gutterSize = 0.25;
  const cellDepth = 0.06;
  const chamferRadius = 0.04;
  const tickWidth = 0.4;
  const tickHeight = 0.05;
  const tickEmissive = 1.3;
  const innerPadding = 0.5;

  // Grid positioning (centered at origin)
  const gridWidth = dominantWidth + gutterSize + secondaryWidth;
  const gridHeight = dominantHeight;

  // Cell positions
  const dominantX = -gridWidth / 2 + dominantWidth / 2;
  const dominantY = 0;

  const secondary1X = -gridWidth / 2 + dominantWidth + gutterSize + secondaryWidth / 2;
  const secondary1Y = gridHeight / 4;

  const secondary2X = secondary1X;
  const secondary2Y = -gridHeight / 4;

  // Header caption
  const captionText = ctx.fontAtlas.createText('ATELIER METRICS / Q2 2026', {
    fontSize: 18,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 2.16, // 0.12em at 18px
  });
  captionText.position.set(-2.75, gridHeight / 2 + 0.5, 0.1);
  group.add(captionText);

  // Helper: create bento cell with gradient, chamfer, and tick
  function createCell(x, y, width, height, valueFontSize, valueText, labelText) {
    const cellGroup = new Group();
    cellGroup.position.set(x, y, 0);

    // Main surface mesh with gradient material
    const surfaceGeom = new BoxGeometry(width, height, cellDepth);

    // TSL material with engineered diagonal gradient
    const surfaceMat = new MeshStandardNodeMaterial({
      colorNode: mix(
        color(colors.gradTop),
        color(colors.gradBottom),
        smoothstep(0.35, 0.55, uv().x) // Hard-stop sheen band at 40%
      ),
      roughness: 0.5,
      metalness: 0.45,
      clearcoat: 0.2,
      side: 2, // DoubleSide for safety
    });

    const surfaceMesh = new Mesh(surfaceGeom, surfaceMat);
    surfaceMesh.castShadow = true;
    surfaceMesh.receiveShadow = true;
    cellGroup.add(surfaceMesh);

    // Tick bar (accent red, emissive)
    const tickGeom = new PlaneGeometry(tickWidth, tickHeight);
    const tickMat = new MeshStandardNodeMaterial({
      color: colors.accent,
      emissive: colors.accent,
      emissiveIntensity: tickEmissive,
      metalness: 0.1,
      roughness: 0.6,
    });
    const tickMesh = new Mesh(tickGeom, tickMat);
    tickMesh.position.set(
      -width / 2 + innerPadding + tickWidth / 2,
      height / 2 - innerPadding - tickHeight / 2,
      cellDepth / 2 + 0.01
    );
    cellGroup.add(tickMesh);

    // Value text
    const valueTextObj = ctx.fontAtlas.createText(valueText, {
      fontSize: valueFontSize,
      color: colors.paper,
      align: 'left',
    });
    valueTextObj.position.set(
      -width / 2 + innerPadding,
      height / 2 - innerPadding - 0.4,
      cellDepth / 2 + 0.02
    );
    cellGroup.add(valueTextObj);

    // Label text
    const labelTextObj = ctx.fontAtlas.createText(labelText, {
      fontSize: 18,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: 1.44, // 0.08em at 18px
    });
    labelTextObj.position.set(
      -width / 2 + innerPadding,
      height / 2 - innerPadding - 0.4 - 0.5,
      cellDepth / 2 + 0.02
    );
    cellGroup.add(labelTextObj);

    return cellGroup;
  }

  // Create dominant cell (left, both rows)
  const dominantCell = createCell(
    dominantX,
    dominantY,
    dominantWidth,
    dominantHeight,
    124, // valueLarge em at 0.62 * 200 = 124px
    '0.002 mm',
    'Case tolerance, CNC pass'
  );
  group.add(dominantCell);

  // Create secondary cells (right column)
  const secondary1Cell = createCell(
    secondary1X,
    secondary1Y,
    secondaryWidth,
    secondaryHeight,
    68, // value em
    '38 h',
    'Power reserve, NA-01'
  );
  group.add(secondary1Cell);

  const secondary2Cell = createCell(
    secondary2X,
    secondary2Y,
    secondaryWidth,
    secondaryHeight,
    68, // value em
    '214',
    'Components per calibre'
  );
  group.add(secondary2Cell);

  // Collect all cells for stagger animation
  const cells = [dominantCell, secondary1Cell, secondary2Cell];

  // Entrance animation: stagger fade-up
  const tlEntrance = gsap.timeline();
  cells.forEach((cell, idx) => {
    cell.children.forEach((child) => {
      child.userData.originalOpacity = child.material?.opacity ?? 1;
      if (child.material) child.material.transparent = true;
    });

    tlEntrance.from(
      cell.children.map((c) => ({ obj: c, y: c.position.y })),
      {
        y: (i) => cell.children[i].position.y + 0.2,
        opacity: 0,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        stagger: { each: 0, onUpdate: function () {} },
      },
      idx * 0.08
    );
  });

  // Hover press-down + weighted-settle
  let isPressed = false;
  function attachCellInteraction(cellGroup) {
    cellGroup.userData.handlers = cellGroup.userData.handlers || {};

    cellGroup.userData.handlers.hover = function (isHovering) {
      if (isHovering && !isPressed) {
        isPressed = true;
        const tlPress = gsap.timeline();
        tlPress.to(cellGroup.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
        });
        tlPress.to(
          cellGroup.scale,
          {
            x: 1.04,
            y: 1.04,
            z: 1.04,
            duration: 0.3,
            ease: 'cubic-bezier(0.165,0.84,0.44,1)',
          },
          0.12
        );
        tlPress.to(
          cellGroup.scale,
          {
            x: 1.0,
            y: 1.0,
            z: 1.0,
            duration: 0.9,
            ease: 'cubic-bezier(0.165,0.84,0.44,1)',
          },
          0.42
        );
      }
    };
  }

  cells.forEach(attachCellInteraction);

  // Cleanup
  group.userData.cleanup = function () {
    if (tlEntrance) tlEntrance.kill();
    cells.forEach((cell) => {
      gsap.killTweensOf(cell.scale);
    });
    group.traverse((node) => {
      if (node.material) {
        node.material.dispose();
      }
      if (node.geometry) {
        node.geometry.dispose();
      }
    });
  };

  return group;
}
